PREFIX in: <http://data.world/schema/insurance/>

SELECT ((SUM(?premiumValue) / COUNT(DISTINCT ?policy)) AS ?averagePolicySize)
WHERE {
  SERVICE <mapped> {
    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy ;
         in:hasPremiumAmount ?premium .
    ?premium in:premiumAmount ?premiumValue .
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
       (SUM(?lossPaymentVal + ?lossReserveVal + ?expensePaymentVal + ?expenseReserveVal) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?pcd .

    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy .

    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:hasPolicyHolder ?policyHolder .

    OPTIONAL {
      ?policyHolder in:policyHolderId ?policyHolderId .
    }

    OPTIONAL {
      ?pcd in:hasPremiumAmount ?premium .
      ?premium in:premiumAmount ?premiumAmount .
    }

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lpAmtRaw .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lrAmtRaw .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?epAmtRaw .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?erAmtRaw .
    }

    BIND(COALESCE(xsd:decimal(?lpAmtRaw), 0) AS ?lossPaymentVal)
    BIND(COALESCE(xsd:decimal(?lrAmtRaw), 0) AS ?lossReserveVal)
    BIND(COALESCE(xsd:decimal(?epAmtRaw), 0) AS ?expensePaymentVal)
    BIND(COALESCE(xsd:decimal(?erAmtRaw), 0) AS ?expenseReserveVal)
  }
}
GROUP BY ?claimNumber ?policyNumber ?policyHolderId ?premiumAmount
ORDER BY ?claimNumber ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolderId ?policyNumber (SUM(?premiumValue) AS ?totalPremiumAmount)
WHERE {
  SERVICE <mapped> {
    ?policyCoverage in:hasPolicy ?policy ;
                    in:hasPremiumAmount ?premium .
    ?policy in:hasPolicyHolder ?policyHolder ;
            in:policyNumber ?policyNumber .
    ?policyHolder in:policyHolderId ?policyHolderId .
    ?premium in:premiumAmount ?premiumValue .
  }
}
GROUP BY ?policyHolderId ?policyNumber
ORDER BY ?policyHolderId ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?policyNumber ?policyHolder ?premiumAmountPaid ?catastrophe ?agent
       ?lossPaymentAmount ?lossReserveAmount ?expensePaymentAmount ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment in:lossPaymentAmount ?lossPaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve in:lossReserveAmount ?lossReserveAmount .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment in:expensePaymentAmount ?expensePaymentAmount .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve in:expenseReserveAmount ?expenseReserveAmount .
    }

    OPTIONAL {
      ?claim in:against ?coverage .
      ?coverage in:hasPolicy ?policy .
      ?policy in:policyNumber ?policyNumber .

      OPTIONAL {
        ?policy in:hasPolicyHolder ?policyHolderResource .
        OPTIONAL { ?policyHolderResource in:policyHolderId ?policyHolder }
      }

      OPTIONAL {
        ?coverage in:hasPremiumAmount ?premium .
        ?premium in:premiumAmount ?premiumAmountPaid .
      }

      OPTIONAL {
        ?policy in:soldByAgent ?agentResource .
        OPTIONAL { ?agentResource in:agentId ?agent }
      }
    }

    OPTIONAL {
      ?claim in:hasCatastrophe ?catastropheResource .
      OPTIONAL { ?catastropheResource in:catastropheName ?catastrophe }
    }
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId ?policyNumber ?claimNumber ?expenseReserveAmount
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:policyNumber ?policyNumber ;
            in:soldByAgent ?agent .

    ?agent a in:Agent ;
           in:agentId ?agentId .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:against ?coverage ;
           in:hasExpenseReserve ?expenseReserve .

    ?expenseReserve a in:ExpenseReserve ;
                    in:expenseReserveAmount ?expenseReserveAmount .
  }
}
ORDER BY ?agentId ?policyNumber ?claimNumber
